"""Bounded local document processing. Input/output paths are generated by the worker."""
import base64
import io
import json
import os
import pathlib
import re
import resource
import shutil
import subprocess
import sys
import zipfile
from pypdf import PdfReader, PdfWriter
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.utils import ImageReader
from PIL import Image, ImageDraw, ImageChops, ImageOps

MAX_PAGES = 300
Image.MAX_IMAGE_PIXELS = 40000000
FONT = '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
pdfmetrics.registerFont(TTFont('DG', FONT))

def run(args, timeout=90):
    return subprocess.run(args, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                          timeout=timeout, env={**os.environ, 'OMP_THREAD_LIMIT': '1'})

def reader(path):
    r = PdfReader(path)
    if r.is_encrypted:
        raise ValueError('Сначала откройте защищённый PDF и сохраните доступную копию.')
    if not 0 < len(r.pages) <= MAX_PAGES:
        raise ValueError('Допустимо от 1 до 300 страниц.')
    for page in r.pages:
        if max(float(page.mediabox.width), float(page.mediabox.height)) > 3000:
            raise ValueError('Слишком большой физический размер страницы.')
    return r

def selection(value, count):
    if not value or not value.strip(): return list(range(count))
    result = []
    for token in value.split(','):
        m = re.fullmatch(r'\s*(\d+)(?:\s*-\s*(\d+))?\s*', token)
        if not m: raise ValueError('Страницы задаются числами и диапазонами: 1, 3-5.')
        start, end = int(m[1]), int(m[2] or m[1])
        if not 1 <= start <= end <= count: raise ValueError('Номер страницы вне документа.')
        result.extend(range(start-1, end))
    if not result or len(result) > MAX_PAGES: raise ValueError('Выберите не более 300 страниц.')
    return result

def image_page(path, page, directory, dpi=150):
    prefix = str(directory / 'render')
    run(['pdftoppm', '-f', str(page+1), '-l', str(page+1), '-singlefile', '-r', str(dpi), '-png', str(path), prefix])
    with Image.open(prefix+'.png') as im: return im.convert('RGB')

def save_pdf(writer, path):
    # Rebuild pages only: do not carry source attachments, actions, or form scripts.
    for p in writer.pages:
        for key in ['/AA', '/Annots']:
            if key in p: del p[key]
    writer.write(path)

def overlay(page, draw):
    page.transfer_rotation_to_content()
    b = io.BytesIO(); c = canvas.Canvas(b, pagesize=(float(page.mediabox.width), float(page.mediabox.height)))
    draw(c, float(page.mediabox.width), float(page.mediabox.height)); c.save(); b.seek(0)
    page.merge_page(PdfReader(b).pages[0])

def image_pdf(images, path, landscape=False, margin=24):
    size = (842, 595) if landscape else (595, 842)
    c = canvas.Canvas(str(path), pagesize=size)
    for im in images:
        if isinstance(im, pathlib.Path):
            with Image.open(im) as source: im = ImageOps.exif_transpose(source).convert('RGB')
        c.drawImage(ImageReader(im), margin, margin, width=size[0]-2*margin, height=size[1]-2*margin,
                    preserveAspectRatio=True, anchor='c'); c.showPage()
    c.save()

def office_pdf(path, directory):
    out = directory / ('office-'+path.stem); out.mkdir()
    profile = (out / 'profile').as_uri()
    run([os.environ.get('LIBREOFFICE_BIN','soffice'), '-env:UserInstallation='+profile, '--headless', '--convert-to', 'pdf', '--outdir', str(out), str(path)])
    pdf = out / (path.stem+'.pdf')
    if not pdf.exists(): raise ValueError('Не удалось преобразовать DOCX в PDF.')
    reader(pdf)
    return pdf

def ocr_pdf(path, directory, languages):
    source = reader(path); w = PdfWriter()
    for i, p in enumerate(source.pages):
        if (p.extract_text() or '').strip(): w.add_page(p); continue
        im = image_page(path, i, directory, 200); png = directory / 'ocr.png'; im.save(png)
        prefix = str(directory / 'ocr-result')
        run(['tesseract', str(png), prefix, '-l', languages, 'pdf'], timeout=60)
        w.add_page(PdfReader(prefix+'.pdf').pages[0])
    out=directory/'searchable.pdf'; save_pdf(w,out); return out

def process(config, directory):
    tool=config['tool']; options=config.get('options', {}); sources=config['files']
    files=[pathlib.Path(f['path']) for f in sources]
    out=directory/'result.pdf'; warnings=[]
    if tool == 'inspect':
        r=reader(files[0]); page=int(options.get('page',1))-1
        if not 0 <= page < len(r.pages): raise ValueError('Страница не найдена.')
        im=image_page(files[0],page,directory,70); im.thumbnail((850,1100)); b=io.BytesIO(); im.save(b,format='JPEG',quality=75)
        return {'pages':len(r.pages),'page':page+1,'image':'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()}
    if tool == 'images-pdf':
        image_pdf(files,out,options.get('landscape',False),options.get('margin',24))
    elif tool == 'docx-pdf':
        shutil.copyfile(office_pdf(files[0],directory),out)
    elif tool == 'bundle' and options.get('format') == 'zip':
        out=directory/'result.zip'
        with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
            entries=[]
            for i,(p,s) in enumerate(zip(files,sources)):
                name=f'{i+1:03d}_'+re.sub(r'[\\/\x00-\x1f]','_',s['title'])
                z.write(p,name);entries.append(f'{i+1}. {s["title"]}')
            z.writestr('Опись.txt','\n'.join(entries))
    elif tool in ('merge','bundle'):
        w=PdfWriter(); counts=[]
        for p in files:
            if p.suffix.lower()=='.docx': p=office_pdf(p,directory)
            elif p.suffix.lower() in ('.png','.jpg','.jpeg'):
                image_out=directory/(p.stem+'.pdf'); image_pdf([p],image_out);p=image_out
            r=reader(p);counts.append(len(r.pages))
            for page in r.pages:w.add_page(page)
            if len(w.pages)>MAX_PAGES:raise ValueError('Комплект превышает 300 страниц.')
        if tool=='bundle' and options.get('inventory',True):
            b=io.BytesIO();c=canvas.Canvas(b,pagesize=(595,842));c.setFont('DG',16);c.drawString(40,795,'Опись документов');y=760;start=1
            for i,s in enumerate(sources):
                # At most 30 entries; wrap names so the inventory remains readable.
                name=f'{i+1}. {s["title"]} — {counts[i]} стр.'
                lines=[name[n:n+65] for n in range(0,len(name),65)]
                for line in lines:
                    if y<45:c.showPage();c.setFont('DG',10);y=795
                    c.setFont('DG',10);c.drawString(40,y,line);y-=15
                y-=7
            c.save();b.seek(0);inv=PdfReader(b)
            for i,page in enumerate(inv.pages):w.insert_page(page,i)
        if tool=='bundle' and options.get('number',True):
            for i,page in enumerate(w.pages):overlay(page,lambda c,x,y,n=i+1:(c.setFont('DG',10),c.drawCentredString(x/2,20,str(n))))
        save_pdf(w,out)
    elif tool == 'ocr':
        p=files[0]
        if p.suffix.lower()!='.pdf':
            p=directory/'image-source.pdf';image_pdf([files[0]],p)
        shutil.copyfile(ocr_pdf(p,directory,options.get('languages','rus+eng')),out)
    elif tool in ('pdf-docx','pdf-xlsx'):
        import pdfplumber
        source=ocr_pdf(files[0],directory,options.get('languages','rus+eng'))
        if tool=='pdf-docx':
            from docx import Document
            from docx.shared import Pt
            doc=Document();doc.styles['Normal'].font.name='Arial';doc.styles['Normal'].font.size=Pt(11)
            with pdfplumber.open(source) as pdf:
                for i,page in enumerate(pdf.pages):
                    if i:doc.add_page_break()
                    tables=page.find_tables();outside=page.filter(lambda obj:not any(t.bbox[0]<=obj.get('x0',-1)<=t.bbox[2] and t.bbox[1]<=obj.get('top',-1)<=t.bbox[3] for t in tables))
                    for line in (outside.extract_text() or '').splitlines():doc.add_paragraph(line)
                    for t in tables:
                        rows=t.extract();cols=max((len(row) for row in rows),default=0)
                        if cols:
                            table=doc.add_table(rows=0,cols=cols);table.style='Table Grid'
                            for row in rows:
                                cells=table.add_row().cells
                                for j,v in enumerate(row):cells[j].text=v or ''
            out=directory/'result.docx';doc.save(out)
            warnings.append('Текст и таблицы восстановлены. Проверьте порядок блоков, числа и оформление; точная верстка PDF не сохраняется.')
        else:
            from openpyxl import Workbook
            wb=Workbook();wb.remove(wb.active);total=0
            with pdfplumber.open(source) as pdf:
                for i,page in enumerate(pdf.pages):
                    tables=page.extract_tables()
                    if not tables:tables=page.extract_tables({'vertical_strategy':'text','horizontal_strategy':'text'})
                    for j,table in enumerate(tables):
                        if not table:continue
                        ws=wb.create_sheet(f'Стр {i+1} таблица {j+1}');total+=1
                        for row in table:
                            ws.append([v or '' for v in row])
                            for cell in ws[ws.max_row]:cell.data_type='s'
                        ws.freeze_panes='A2'
                        for col in ws.columns:ws.column_dimensions[col[0].column_letter].width=25
            if not total:raise ValueError('Таблицы не обнаружены. Попробуйте более чёткий скан.')
            out=directory/'result.xlsx';wb.save(out);warnings.append('Проверьте границы таблиц и суммы. Значения сохранены как текст, чтобы избежать потери реквизитов.')
    elif tool == 'compare':
        rs=[reader(p) for p in files];count=max(len(r.pages) for r in rs);c=canvas.Canvas(str(out),pagesize=(1190,900));changed=[]
        for i in range(count):
            ims=[image_page(p,i,directory,80) if i<len(r.pages) else Image.new('RGB',(660,935),'white') for p,r in zip(files,rs)]
            ims=[ImageOps.pad(im,(660,935),color='white') for im in ims]
            mask=ImageChops.difference(*ims).convert('L').point(lambda p:255 if p>30 else 0)
            if mask.getbbox():
                changed.append(i+1)
                tint=Image.new('RGB',ims[1].size,'#ff6b6b');ims[1]=Image.composite(Image.blend(ims[1],tint,.45),ims[1],mask)
            c.setFont('DG',11);c.drawString(30,875,f'Страница {i+1} • '+('Есть различия' if mask.getbbox() else 'Без видимых различий'))
            c.drawString(30,852,'Исходная редакция');c.drawString(610,852,'Новая редакция — изменения выделены')
            for j,im in enumerate(ims):c.drawImage(ImageReader(im),30+j*580,20,width=550,height=815,preserveAspectRatio=True,anchor='c')
            c.showPage()
        c.save();warnings.append('Визуальные различия на страницах: '+(', '.join(map(str,changed)) or 'не обнаружены')+'. Проверка выполнена по изображению страниц.')
    elif tool == 'redact':
        import pdfplumber
        r=reader(files[0]);rects=options.get('rects',[]);terms=[t.strip() for t in options.get('terms','').splitlines() if t.strip()]
        c=canvas.Canvas(str(out));found=0
        with pdfplumber.open(files[0]) as pdf:
            for i,page in enumerate(pdf.pages):
                im=image_page(files[0],i,directory,180);draw=ImageDraw.Draw(im);boxes=[]
                for box in rects:
                    if box['page']==i+1:boxes.append((box['x']*im.width,box['y']*im.height,(box['x']+box['w'])*im.width,(box['y']+box['h'])*im.height))
                for term in terms:
                    for hit in page.search(term,regex=False,case=False):boxes.append((hit['x0']/page.width*im.width-2,hit['top']/page.height*im.height-2,hit['x1']/page.width*im.width+2,hit['bottom']/page.height*im.height+2))
                for box in boxes:draw.rectangle(box,fill='black');found+=1
                c.setPageSize((page.width,page.height));c.drawImage(ImageReader(im),0,0,width=page.width,height=page.height);c.showPage()
        if not found:raise ValueError('Совпадений не найдено. На скане выделите области вручную.')
        c.save();warnings.append(f'Удалено областей: {found}. Копия состоит из изображений, без исходного текста, вложений и метаданных. Проверьте все страницы перед передачей.')
    else:
        r=reader(files[0]);w=PdfWriter();indices=selection(options.get('pages',''),len(r.pages))
        if tool=='pages':
            if options.get('mode')=='delete':indices=[i for i in range(len(r.pages)) if i not in indices]
            if not indices:raise ValueError('Нельзя удалить все страницы.')
            if options.get('mode')=='split':
                out=directory/'result.zip'
                with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
                    for j,i in enumerate(indices):
                        part=PdfWriter();part.add_page(r.pages[i]).rotate(options.get('rotation',0));b=io.BytesIO();save_pdf(part,b);z.writestr(f'{j+1:03d}_страница_{i+1}.pdf',b.getvalue())
                return {'outputs':[{'file':out.name}], 'warnings':warnings}
            for i in indices:w.add_page(r.pages[i]).rotate(options.get('rotation',0))
        else:
            for p in r.pages:w.add_page(p)
            if tool in ('number','watermark'):
                for offset,i in enumerate(indices):
                    def draw(c,x,y):
                        if tool=='number':
                            c.setFont('DG',11);text=str(options.get('start',1)+offset)
                            if options.get('position')=='top':c.drawCentredString(x/2,y-24,text)
                            else:c.drawCentredString(x/2,20,text)
                        else:
                            c.saveState();c.setFillAlpha(options.get('opacity',.2));c.translate(x/2,y/2);c.rotate(35);c.setFont('DG',min(44, x/max(len(options['text']),1)*1.2));c.drawCentredString(0,0,options['text']);c.restoreState()
                    overlay(w.pages[i],draw)
            elif tool=='protect':w.encrypt(options['password'],algorithm='AES-256')
            elif tool!='compress':raise ValueError('Неизвестная операция.')
        save_pdf(w,out)
        if tool=='compress':
            compact=directory/'compact.pdf';quality=options.get('quality','balanced');dpi={'small':96,'balanced':150,'print':220}[quality]
            run(['gs','-sDEVICE=pdfwrite','-dCompatibilityLevel=1.7','-dNOPAUSE','-dBATCH','-dSAFER','-dDownsampleColorImages=true','-dDownsampleGrayImages=true',f'-dColorImageResolution={dpi}',f'-dGrayImageResolution={dpi}','-sOutputFile='+str(compact),str(out)])
            if compact.stat().st_size<out.stat().st_size:shutil.copyfile(compact,out)
            if out.stat().st_size>=files[0].stat().st_size:
                shutil.copyfile(files[0],out);warnings.append('Дополнительное сжатие не уменьшило размер: сохранено исходное качество.')
    if not out.exists() or not out.stat().st_size:raise ValueError('Обработка не создала результат.')
    if out.stat().st_size>100*1024*1024:raise ValueError('Результат превышает 100 МБ.')
    return {'outputs':[{'file':out.name}], 'warnings':warnings, 'inputBytes':sum(p.stat().st_size for p in files),'outputBytes':out.stat().st_size}

if __name__=='__main__':
    resource.setrlimit(resource.RLIMIT_AS,(2*1024**3,2*1024**3))
    resource.setrlimit(resource.RLIMIT_FSIZE,(150*1024**2,150*1024**2))
    try:
        cfg=pathlib.Path(sys.argv[1]).resolve();result=process(json.loads(cfg.read_text()),cfg.parent)
        print(json.dumps(result,ensure_ascii=False))
    except ValueError as e:print(json.dumps({'error':str(e)},ensure_ascii=False));sys.exit(2)
    except Exception:print(json.dumps({'error':'Файл не удалось обработать. Проверьте формат, целостность и доступность содержимого.'},ensure_ascii=False));sys.exit(2)
